import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort
import xml.etree.ElementTree as ET
import requests

app = Flask(__name__)

SECRET_KEY = os.environ.get('WEBHOOK_SECRET', 'default-secret-key')
INTERNAL_API = os.environ.get('INTERNAL_API', 'http://internal-service:8080')

def verify_signature(payload, signature):
    """Verify webhook signature using HMAC-SHA256"""
    if not signature:
        return False
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f"sha256={expected}", signature)

def parse_notification(xml_data):
    """Parse incoming XML notification from partner system"""
    try:
        root = ET.fromstring(xml_data)
        notification = {
            'event_type': root.find('event').text,
            'timestamp': root.find('timestamp').text,
            'source': root.find('source').text,
            'payload': {}
        }
        payload_elem = root.find('payload')
        if payload_elem is not None:
            for child in payload_elem:
                notification['payload'][child.tag] = child.text
        return notification
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}")

def enrich_notification(notification):
    """Enrich notification with data from internal service"""
    source = notification.get('source', '')
    event_type = notification.get('event_type', '')

    # Fetch enrichment data from internal API
    enrichment_url = f"{INTERNAL_API}/enrich?source={source}&type={event_type}"
    try:
        resp = requests.get(enrichment_url, timeout=5)
        if resp.status_code == 200:
            notification['enrichment'] = resp.json()
    except requests.RequestException:
        notification['enrichment'] = None

    return notification

def process_callback(notification):
    """Process callback URL if present in notification payload"""
    callback_url = notification.get('payload', {}).get('callback_url')
    if callback_url:
        # Validate callback is from known partner
        if not callback_url.startswith(('http://', 'https://')):
            return None
        try:
            resp = requests.get(callback_url, timeout=10, allow_redirects=False)
            return resp.text[:4096]
        except requests.RequestException:
            return None
    return None

@app.route('/webhook/notify', methods=['POST'])
def receive_notification():
    """Receive XML notification from partner webhook"""
    content_type = request.content_type or ''
    if 'xml' not in content_type.lower() and 'text' not in content_type.lower():
        abort(415, 'Unsupported content type')

    raw_body = request.get_data()

    # Signature verification (optional in dev mode)
    sig = request.headers.get('X-Webhook-Signature')
    if os.environ.get('REQUIRE_SIG', 'false') == 'true':
        if not verify_signature(raw_body, sig):
            abort(401, 'Invalid signature')

    try:
        notification = parse_notification(raw_body)
    except ValueError as e:
        abort(400, str(e))

    notification = enrich_notification(notification)
    callback_result = process_callback(notification)

    if callback_result:
        notification['callback_response'] = callback_result

    return jsonify({
        'status': 'processed',
        'event_type': notification.get('event_type'),
        'timestamp': notification.get('timestamp'),
        'has_enrichment': notification.get('enrichment') is not None,
        'callback_received': callback_result is not None
    })

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'time': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)
